const ThreeJSRuntimeRootMemo = React.memo(ThreeJSRuntimeRoot as any)
const ThreeJSRuntimeSlotMemo = React.memo(ThreeJSRuntimeSlot as any)

/**
 * @framerSupportedLayoutWidth any-prefer-fixed
 * @framerSupportedLayoutHeight any-prefer-fixed
 * @framerIntrinsicWidth 800
 * @framerIntrinsicHeight 600
 *
 * @framerDisableUnlink
 */
// @api PublicExport.ThreeJS_Runtime
export default function ThreeJS_Runtime(props: any) {
    const { role = "slot" } = props
    const nimbusTechId = useId()
    const [nimbusHover, setNimbusHover] = React.useState(false)
    if (props.nimbusTech && role !== "root")
        return (
            <div
                data-nimbus-tech={nimbusTechId}
                style={{
                    ...props.style,
                    position: "relative",
                    width: "100%",
                    height: "100%",
                }}
            >
                <ThreeJSRuntimeSlotMemo
                    {...props}
                    nimbusTechId={nimbusTechId}
                    style={{
                        position: "absolute",
                        inset: 0,
                        width: "100%",
                        height: "100%",
                    }}
                    onModelHoverStart={(event: any) => {
                        setNimbusHover(true)
                        props.onModelHoverStart?.(event)
                    }}
                    onModelHoverEnd={(event: any) => {
                        setNimbusHover(false)
                        props.onModelHoverEnd?.(event)
                    }}
                    onModelClick={(event: any) => { window.dispatchEvent(new CustomEvent("botanika:nimbus-tech-open-overview", { detail: { id: nimbusTechId } })) }}
                    asGroup={role === "group" || !!props.asGroup}
                />
                <NimbusTechUI
                    labelStyle={props.nimbusLabels}
                    id={nimbusTechId}
                    hover={nimbusHover}
                    onOpen={() => props.onModelClick?.()}
                />
            </div>
        )
    if (role === "root") return <ThreeJSRuntimeRootMemo {...props} />
    return (
        <ThreeJSRuntimeSlotMemo
            {...props}
            asGroup={role === "group" || !!props.asGroup}
        />
    )
}

// Expose globally so splash screen or external scripts can trigger preload early
if (typeof window !== "undefined") {
    ;(window as any).__preloadModel3D = _startModelPreload
}

ThreeJS_Runtime.defaultProps = {
    ...(ThreeJSRuntimeSlot as any).defaultProps,
    ...(ThreeJSRuntimeRoot as any).defaultProps,
    role: "slot",
    asGroup: false,
    groupName: "",
}
